ATL_SRC.push(['@atl/forms/calloff.js', 0, `// Fills in the Employee Call-Off, Tardy & PTO Form (Word) for attendance findings from the HR timesheet import.
// Fills Section 1 (employee), Section 2 (call-off / late arrival record) and the Management signature line;
// Section 3 (PTO request) and the employee / HR signatures stay blank for signing by hand.
import { CALLOFF_PARTS } from '@atl/forms/calloff-template.js';
import { zip } from '@atl/util.js';

const W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
/** The form's Reason boxes (Other takes the note as its text). */
export const REASONS = ['Illness', 'Bereavement', 'Report Late', 'Accident', 'Personal', 'Other'];
export const ABSENCE_TYPES = ['Call Off', 'Late Arrival', 'No Call / No Show'];
export const SICK = ['Self', 'Spouse', 'Parent', 'Child'];

let parts; // template parts, decoded once
const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const t12 = hhmm => { if (!hhmm) return ''; const [h, m] = hhmm.split(':').map(Number); return \`\${((h + 11) % 12) + 1}:\${String(m).padStart(2, '0')} \${h < 12 ? 'AM' : 'PM'}\`; };
const us = iso => \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\`;
const DOW = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/**
 * f: { name, date (ISO), type: 'Tardy' | 'Absent' | 'Left Early', absenceType (one of ABSENCE_TYPES), timeOfCall 'HH:MM',
 *      scheduled 'HH:MM', arrival, leftEarly, minutes, reason (one of REASONS), sick (one of SICK), driverCalled 'Yes' | 'No',
 *      usesPto 'Yes' | 'No', ptoDays, note, excused 'Y' | 'N', manager, signDate (ISO), entryId, source } → Blob (.docx)
 */
export function callOffDocx(f) {
  parts ||= CALLOFF_PARTS.map(([p, kind, c]) => [p, kind === 'b64' ? b64(c) : c]);
  return zip(parts.map(([p, c]) => [p, p === 'word/document.xml' ? fill(c, f) : c]), DOCX);
}

/** "AGUILERA, LEXY – 2026-10-19 – Tardy.docx" style file name. */
export function callOffFileName(f) {
  const n = String(f.name).trim().split(/\\s+/), name = n.length > 1 ? \`\${n.slice(1).join(' ')}, \${n[0]}\` : n[0];
  return \`\${name} – \${f.date} – \${f.type}.docx\`.replace(/[\\\\/:*?"<>|]/g, '-');
}

function fill(xml, f) {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  const all = (el, tag) => [...el.getElementsByTagNameNS(W, tag)];
  const text = el => all(el, 't').map(t => t.textContent).join('').trim();
  const up = (el, tag) => { while (el && !(el.namespaceURI === W && el.localName === tag)) el = el.parentNode; return el; };
  const table = title => up(all(doc, 'tc').find(tc => text(tc).startsWith(title)), 'tbl');
  const s1 = table('SECTION 1'), s2 = table('SECTION 2'), s4 = table('SECTION 4');
  if (!s1 || !s2 || !s4) throw new Error('The Call-Off form template has changed — Sections 1, 2 and 4 were not found.');
  // The empty cell to the right of a label cell.
  const after = (tbl, label) => { let tc = all(tbl, 'tc').find(c => text(c) === label)?.nextSibling; while (tc && tc.localName !== 'tc') tc = tc.nextSibling; return tc; };
  const el = (tag, attrs = {}) => { const e = doc.createElementNS(W, 'w:' + tag); for (const [k, v] of Object.entries(attrs)) e.setAttributeNS(W, 'w:' + k, v); return e; };
  const put = (tc, lines) => {
    if (!tc) return;
    const p = all(tc, 'p')[0];
    [].concat(lines).filter(Boolean).forEach((line, i) => {
      const r = el('r'), rPr = el('rPr');
      rPr.append(el('sz', { val: '20' }), el('szCs', { val: '20' })); r.append(rPr);
      if (i) r.append(el('br'));
      const t = el('t'); t.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve'); t.textContent = line; r.append(t);
      p.append(r);
    });
  };
  // Tick a "☐ Option" box inside \`scope\` (a table or a cell): the boxes are typed characters inside one text run per line.
  const tick = (scope, option, replace) => {
    if (!scope || !option) return;
    const t = all(scope, 't').find(x => x.textContent.includes('☐ ' + option));
    if (t) t.textContent = t.textContent.replace(new RegExp('☐ ' + option.replace(/[.*+?^\${}()|[\\]\\\\/]/g, '\\\\$&') + (replace ? '[: _]*' : '')), replace ?? '☒ ' + option);
  };

  // Section 1 — employee
  put(after(s1, 'Employee Name:'), f.name);
  put(after(s1, 'Date:'), \`\${us(f.date)} (\${DOW[new Date(f.date + 'T12:00:00').getDay()]})\`);

  // Section 2 — call-off / late arrival record
  put(after(s2, 'Time of Call:'), t12(f.timeOfCall));
  put(after(s2, 'Time Scheduled:'), t12(f.scheduled));
  tick(s2, f.absenceType);
  // Minutes late follow the arrival and scheduled times shown on the form (either may have been corrected in the popup).
  const mins = hhmm => { const [h, m] = String(hhmm || '').split(':').map(Number); return h * 60 + m; };
  const lateBy = f.arrival && f.scheduled ? mins(f.arrival) - mins(f.scheduled) : f.minutes;
  if (f.arrival && (f.type === 'Tardy' || f.absenceType === 'Late Arrival')) put(after(s2, 'If Late, Arrival Time:'), \`\${t12(f.arrival)}\${lateBy > 0 ? \` (\${lateBy} min late)\` : ''}\`);
  tick(after(s2, 'No Show – Driver Called?'), f.driverCalled);
  if (f.reason === 'Other') tick(s2, 'Other', \`☒ Other: \${f.note || '______________'}\`);
  else tick(s2, f.reason);
  tick(s2, f.sick);
  tick(after(s2, 'Uses Available PTO?'), f.usesPto);
  put(after(s2, 'PTO Days Remaining:'), f.ptoDays === '' || f.ptoDays == null ? '' : String(f.ptoDays));
  put(after(s2, 'Manager Name:'), f.manager || '');
  put(after(s2, 'Comments:'), [
    f.type === 'Tardy' ? \`Tardy — clocked in at \${t12(f.arrival)}, \${lateBy} minutes late (scheduled \${t12(f.scheduled)}).\`
      : f.type === 'Absent' ? \`Absent — no time entries on \${DOW[new Date(f.date + 'T12:00:00').getDay()]} \${us(f.date)}.\`
      : \`Left early — last clock-out \${t12(f.leftEarly)} (before 4:00 PM; shift ends 4:30 PM).\`,
    \`\${f.excused === 'Y' ? 'Excused' : 'Unexcused'}.\`,
    f.note && f.reason !== 'Other' ? \`Note: \${f.note}\` : '',
    \`Source: \${f.source || 'HR timesheet import'}\${f.entryId ? \` · Attendance Log \${f.entryId}\` : ''}.\`,
  ]);

  // Section 4 — the manager signs (typed name) and dates it; the label cell "Date:" takes the date after the label.
  if (f.manager) {
    const sig = after(s4, 'Management Signature:');
    put(sig, f.manager);
    let dateCell = sig?.nextSibling; while (dateCell && dateCell.localName !== 'tc') dateCell = dateCell.nextSibling;
    if (dateCell && text(dateCell) === 'Date:') { const p = all(dateCell, 'p')[0], r = el('r'), rPr = el('rPr'), t = el('t');
      rPr.append(el('sz', { val: '20' }), el('szCs', { val: '20' })); t.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve');
      t.textContent = ' ' + us(f.signDate || new Date().toISOString().slice(0, 10)); r.append(rPr, t); p.append(r); }
  }

  // The template's ☐ boxes have no font of their own, so Word substitutes one that draws them as tiny asterisks.
  // Put every box in its own run in Segoe UI Symbol (on every Windows PC) so ☐ / ☒ show as real boxes.
  for (const t of all(doc, 't').filter(x => /[☐☒]/.test(x.textContent))) {
    const r = t.parentNode, rPr = all(r, 'rPr')[0];
    for (const piece of t.textContent.split(/([☐☒])/).filter(Boolean)) {
      const nr = el('r'), nt = el('t');
      const pr = rPr ? rPr.cloneNode(true) : el('rPr');
      if (/^[☐☒]$/.test(piece)) { for (const old of all(pr, 'rFonts')) old.remove(); pr.prepend(el('rFonts', { ascii: 'Segoe UI Symbol', hAnsi: 'Segoe UI Symbol', eastAsia: 'Segoe UI Symbol', cs: 'Segoe UI Symbol' })); }
      nt.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve'); nt.textContent = piece;
      nr.append(pr, nt); r.parentNode.insertBefore(nr, r);
    }
    r.remove();
  }
  // Some browsers keep the XML declaration when serializing and some drop it; write exactly one.
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\r\\n' + new XMLSerializer().serializeToString(doc).replace(/^<\\?xml[^>]*\\?>\\s*/, '');
}`]);

