  mhe: { label: 'MHE Fleet Register', hash: '#/import', input: '[data-file]', admin: true },
  billing: { label: 'Billing Activity (customer throughput)', hash: '#/weekly', tab: 'customer', drop: '[data-tp-drop]' },
  elxBilling: { label: 'Electrolit Billing Activity (more than one week — scorecard, split by week into Customer Throughput)', hash: '#/electrolit?tab=drops', drop: '[data-drop="billing"]', page: 'the Electrolit scorecard' },
