    // Training records: "sign-in", "microtraining", "PWH-MTR-2027-W01", "safety meeting" …
    if (/sign.?in|microtraining|training|safety meeting|company meeting|handout|pwh.?mt[rg]/.test(n)) return 'trainScan';
    if (/\\bmhe\\b|forklift|checklist|inspection|pre-?op|week ?ending|weekend|\\bwe\\s*\\d/.test(n) || /^\\d{4,}\\s+\\d{1,3}\\.pdf$/.test(n)) return 'mheInsp';
    if (/hours|overview|payroll|time|counter/.test(n)) return 'hr';
    // A scan with no text at all is a checklist (HR, rail and invoice PDFs have text).
    // A scan with no text: a training record (its header names the meeting) or a forklift checklist.
    if (await noText(f)) return (await (await import('@atl/trainscan.js')).isTrainingScan(f)) ? 'trainScan' : 'mheInsp';
