  const sameDay = delivered.filter(m => documentedOnTime(m.r, cfg)).length;
  const asked = delivered.reduce((a, m) => a + (n0(m.r.kcAsked) || 0), 0), right = delivered.reduce((a, m) => a + Math.min(n0(m.r.kcCorrect) || 0, n0(m.r.kcAsked) || 0), 0);
