ATL_SRC.push(['@atl/views/command.js', 0, `// Command Center (landing page): the state of both buildings and what needs action, on one screen.
// Read-only — every figure comes from the same calculations as the dashboards, rail and Data Quality pages.
import { store } from '@atl/store.js';
import { dashboard, railSummary, derive, dataQuality, dataStatus } from '@atl/calc.js';
import { esc, fmtPct, fmtNum, fmtMoney, todayISO } from '@atl/util.js';
import { kpi, chart, chartBox } from '@atl/ui.js';
import { NEEDS, prodData, prodVs } from '@atl/views/dashboard.js';
import { otifWaiting, oshaReport } from '@atl/forms/incident.js';
import { overdueUploads, itemText, UPLOAD_NEEDS, shortDate } from '@atl/uploads.js';
import { uploadsCard, wireUploads } from '@atl/views/uploadsui.js';
import { mySites, seesAtlanta, siteLabel, unitOf, canSee } from '@atl/sites.js';
import { unitsAt, UNIT_LABEL, UNIT_WORD } from '@atl/throughput.js';

const md = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}\` : '');
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// ---------- monthly reports (6049 / 6021 KPI, Electrolit) ----------
/** The month the reports are for: last month. */
export const reportMonth = () => { const d = new Date(), p = new Date(d.getFullYear(), d.getMonth() - 1, 1); return \`\${p.getFullYear()}-\${String(p.getMonth() + 1).padStart(2, '0')}\`; };
// One KPI report per location the person sees; the customer reports for those who see their building.
const REPORT_LIST = () => [
  // (a new location only once it has labor or throughput posted, so it isn't flagged "not sent" before it starts)
  ...mySites().filter(b => ['6049', '6021'].includes(b) || ['labor', 'throughput'].some(c => store.rows(c).some(r => String(r.building) === b))).map(b => ({ key: 'kpi' + b, label: \`Facility \${siteLabel(b)} — monthly KPI report\`, kind: 'kpiMonthly', building: b, href: \`#/dashboard/\${b}\` })),
  ...(canSee('6049') ? [{ key: 'elx', label: 'Electrolit — monthly performance report', kind: 'elxMonthly', building: '6049', href: '#/electrolit' }] : []),
  ...(canSee('6021') ? [{ key: 'wr', label: 'Smurfit WestRock — monthly performance report', kind: 'wrMonthly', building: '6021', href: '#/westrock' }] : []),
];
/**
 * Status of each monthly report for month ym, from the Sent Reports Archive: Sent (emailed), Prepared (Word / PDF
 * made but not emailed) or Not started. Electrolit copies archived before building folders count as 6049.
 */
export function monthlyReports(ym = reportMonth()) {
  const arch = store.rows('archive').filter(e => e.year === ym.slice(0, 4) && e.month === ym.slice(5, 7));
  return REPORT_LIST().map(r => {
    const mine = arch.filter(e => e.kind === r.kind && (e.building === r.building || (!e.building && r.kind === 'elxMonthly'))).sort((a, b) => String(b.sentAt).localeCompare(String(a.sentAt)));
    const sent = mine.find(e => e.emailed), prepared = mine[0];
    return { ...r, ym, sent, prepared, status: sent ? 'Sent' : prepared ? 'Prepared' : 'Not started' };
  });
}
const OT_RED = 0.08; // same 8% rule as the Overtime section
const PROD_TONE = { 'On Target': 'good', Close: 'warn', Below: 'bad' };
const pill = (tone, text) => \`<span class="pill \${tone}">\${esc(text)}</span>\`;

/** Rail cars still on hand (within the open-car window, not released) with 2 or fewer free days left. */
export function carsRunningOut() {
  const win = store.rail?.openCarWindowDays ?? 30, from = new Date(Date.now() - win * 864e5).toISOString().slice(0, 10);
  return derive('railcars').filter(r => r.status && r.status !== 'Released' && String(r.cpDate) >= from && typeof r.remainingFree === 'number' && r.remainingFree <= 2)
    .sort((a, b) => a.remainingFree - b.remainingFree || String(a.cpDate).localeCompare(String(b.cpDate)));
}

/** The short list of things that are off target or overdue right now: [tone, badge, title, detail, href]. */
export function exceptions(year) {
  const s = store.settings, out = [], due = carsRunningOut();
  // Safety first: OSHA severe-injury reports not yet made, recordables with no report, overdue corrective actions.
  const sev = store.rows('incidents').filter(r => oshaReport(r) && !r.oshaReportedOn);
  if (sev.length) out.push(['bad', sev.length, \`\${sev.length} severe injur\${sev.length === 1 ? 'y' : 'ies'} not yet reported to OSHA\`, sev.map(r => \`\${r.id} — within \${oshaReport(r).hours} h\`).join(' · '), \`#/safety?open=\${encodeURIComponent(sev[0].id)}\`]);
  const wait = otifWaiting();
  if (wait.length) out.push(['bad', wait.length, \`\${wait.length} recordable incident\${wait.length === 1 ? '' : 's'} missing a required Safety Incident report\`, wait.slice(0, 3).map(r => r.id).join(' · ') + ' — OTIF Log, form PWH-FRM-204-1', '#/safety']);
  const late = store.rows('incidents').filter(r => r.status !== 'Closed' && (r.correctives || []).some(c => c.action && c.done !== 'Done' && c.due && c.due < todayISO()));
  if (late.length) out.push(['warn', late.length, \`\${late.length} safety report\${late.length === 1 ? '' : 's'} with overdue corrective actions\`, late.slice(0, 3).map(r => r.id).join(' · '), '#/safety']);
  // Weekly uploads still missing on Tuesday from 9:00 AM (due Monday).
  const upl = overdueUploads();
  if (upl.length) out.push(['bad', upl.length, \`\${upl.length} weekly upload\${upl.length === 1 ? '' : 's'} late (due Monday)\`, \`\${upl.slice(0, 4).map(itemText).join(' · ')}\${upl.length > 4 ? ' …' : ''} — week ending \${[...new Set(upl.map(u => shortDate(u.we)))].join(', ')}\`, '#/?focus=uploads']);
  if (due.length) out.push(['bad', due.length, \`\${due.length} rail car\${due.length === 1 ? '' : 's'} at or near the end of free time\`, \`\${due.filter(r => r.remainingFree <= 0).length} already billable · \${due.filter(r => r.remainingFree > 0).length} within 2 business days\`, '#/rail']);
  for (const bb of mySites()) {
    const p = prodData(bb, year), wk = p.weeks.filter(w => w.rNc > 0), last3 = wk.slice(-3), [t] = p.T.op;
    if (last3.length === 3 && last3.every(w => prodVs(w.rNc, ...p.T.op) === 'Below'))
      out.push(['warn', '3w', \`\${bb} productivity below target 3 weeks running\`, \`\${last3.map(w => fmtNum(w.rNc, 1)).join(' → ')} \${UNIT_WORD[unitOf(bb)]}/hr (target \${fmtNum(t, 1)})\`, \`#/dashboard/\${bb}?tab=prod\`]);
    const ot = dashboard(bb, year).otWeeklyAll.slice(-4).filter(w => typeof w.pct === 'number' && w.pct > OT_RED);
    if (ot.length) out.push(['warn', ot.length, \`\${bb}: \${ot.length} of the last 4 weeks above 8% OT\`, ot.map(w => \`wk \${md(w.week)} \${fmtPct(w.pct, 1)}\`).join(' · '), \`#/dashboard/\${bb}?tab=ot\`]);
  }
  // Monthly reports for last month not emailed yet — flagged from the 5th of the month.
  if (new Date().getDate() >= 5) {
    const ym = reportMonth(), open = monthlyReports(ym).filter(r => r.status !== 'Sent');
    if (open.length) out.push(['warn', open.length, \`\${open.length} monthly report\${open.length === 1 ? '' : 's'} for \${MONTHS[+ym.slice(5, 7) - 1]} not sent yet\`, open.map(r => \`\${r.key === 'elx' ? 'Electrolit' : r.key === 'wr' ? 'WestRock' : r.building + ' KPI'} (\${r.status.toLowerCase()})\`).join(' · '), open[0].href]);
  }
  const fix = dataQuality().filter(c => c.severity === 'FIX').reduce((a, c) => a + c.ids.length, 0);
  if (fix) out.push(['bad', fix, \`\${fix} data quality item\${fix === 1 ? '' : 's'} to fix before reporting\`, 'Duplicates, missing dates, CP / release gaps', '#/quality']);
  for (const r of dataStatus().filter(r => !String(r.status).startsWith('✓')).slice(0, 3)) out.push(['info', '!', \`\${r.feed}: \${String(r.status).replace(/^⚠\\s*/, '')}\`, r.latest ? \`Latest entry \${md(r.latest)}\` : 'No entries yet', r.route]);
  const claims = derive('damage').filter(r => ['Open', 'Filed'].includes(r.claimStatus)).length;
  if (claims) out.push(['info', claims, \`\${claims} damage claim\${claims === 1 ? '' : 's'} open\`, 'Claim status Open / Filed', '#/log/damage']);
  return out;
}

export default {
  needs: () => [...new Set([...NEEDS, 'railcars', 'incidents', 'archive', ...UPLOAD_NEEDS])],
  render() {
    const s = store.settings, y = s.reportingYear;
    // The tiles: Combined Atlanta for those who see both Atlanta buildings, else their (first) location.
    const ids = mySites(), scope = seesAtlanta() ? 'all' : ids[0] || 'all';
    const all = dashboard(scope, y), rail = railSummary(y), per = ids.map(b => ({ b, d: dashboard(b, y), p: prodData(b, y) }));
    const ex = exceptions(y), due = carsRunningOut();
    const acc = d => d.otifMonthly.filter(m => m.accuracy !== '').map(m => m.accuracy * 100);
    const att = d => d.attMonthly.filter(m => m.rate !== '' && m.total).map(m => m.rate * 100);
    const tone = (v, t, higher = true) => (typeof v !== 'number' ? '' : (higher ? v >= t : v <= t) ? 'good' : 'bad');
    const prodTone = p => PROD_TONE[prodVs(p.ytd.rNc, ...p.T.op)] || '';
    const tiles = [
      kpi('Order accuracy · YTD', fmtPct(all.otifYTD.accuracy, 2), \`Target \${fmtPct(s.orderAccuracyTarget)}\`, tone(all.otifYTD.accuracy, s.orderAccuracyTarget), { status: true, spark: acc(all) }),
      kpi('Attendance · YTD', fmtPct(all.attYTD.rate), \`Target \${fmtPct(s.attendanceTarget)}\`, tone(all.attYTD.rate, s.attendanceTarget), { status: true, spark: att(all) }),
      kpi('OT % · YTD', fmtPct(all.otYTD.pct), '8% threshold', tone(all.otYTD.pct, OT_RED, false), { status: all.otYTD.pct > OT_RED ? 'Above 8%' : 'Under 8%', spark: all.otWeeklyAll.slice(-13).map(w => (typeof w.pct === 'number' ? w.pct * 100 : null)) }),
      ...per.map(({ b, p }) => kpi(\`\${UNIT_LABEL[unitOf(b)]} / hr · \${b}\`, p.ytd.rNc ? fmtNum(p.ytd.rNc, 1) : '-', \`Target \${fmtNum(p.T.op[0], 1)} · w/o clerical\`, prodTone(p), { status: true, spark: p.weeks.slice(-13).map(w => w.rNc || null) })),
      ...(rail.byCustomer.length ? [kpi('Demurrage exposure · YTD', fmtMoney(rail.ytd.demurrage), \`\${fmtNum(rail.onHandTotal)} cars on hand now\`, '')] : []),
    ];
    const cellPct = (v, t, d = 1) => \`\${fmtPct(v, d)} \${typeof v === 'number' ? pill(v >= t ? 'good' : 'bad', v >= t ? 'On' : 'Below') : ''}\`;
    const row = ({ b: bb, d, p }) => {
      const pv = prodVs(p.ytd.rNc, ...p.T.op), unit = UNIT_WORD[unitOf(bb)];
      return \`<tr data-href="#/dashboard/\${bb}" tabindex="0"><td><b>\${esc(siteLabel(bb))}</b> <span class="muted">· \${esc(unitsAt(bb).map(u => UNIT_LABEL[u]).join(', '))}</span></td>
        <td class="num">\${cellPct(d.otifYTD.accuracy, s.orderAccuracyTarget, 2)}</td><td class="num">\${cellPct(d.attYTD.rate, s.attendanceTarget)}</td>
        <td class="num">\${fmtPct(d.otYTD.pct, 1)}</td><td class="num">\${fmtNum(d.dmgYTD.n)}</td>
        <td class="num">\${p.ytd.rNc ? fmtNum(p.ytd.rNc, 1) : '-'} <small class="muted">\${unit}/hr</small> \${pv ? pill(PROD_TONE[pv], pv === 'On Target' ? 'On' : pv) : ''}</td>
        <td class="num">\${fmtNum(d.tpYTD.total)} <small class="muted">\${unit}</small></td>
        <td class="num">\${fmtMoney(rail.byBuilding.find(x => x.building === bb)?.ytd.demurrage || 0)}</td></tr>\`;
    };
    const rate = c => (store.rail.customers.find(x => x.name === c) || {}).rate ?? 40;
    // Monthly reports card: last month's 6049 / 6021 KPI and Electrolit reports.
    const rym = reportMonth(), reps = monthlyReports(rym), rMon = \`\${MONTHS[+rym.slice(5, 7) - 1]} \${rym.slice(0, 4)}\`;
    const RT = { Sent: 'good', Prepared: 'warn', 'Not started': 'bad' };
    const when = iso => (iso ? new Date(iso).toLocaleDateString('en-US', { month: 'numeric', day: 'numeric' }) : '');
    const repCard = \`<section class="card cc-card cc-reports"><div class="cc-h"><h2>Monthly reports — \${esc(rMon)}</h2>\${pill(reps.every(r => r.status === 'Sent') ? 'good' : 'warn', \`\${reps.filter(r => r.status === 'Sent').length} of \${reps.length} sent\`)}</div>
      <div class="table-wrap"><table class="grid cc-table"><thead><tr><th>Report</th><th>Status</th><th>Sent / prepared</th><th></th></tr></thead><tbody>
      \${reps.map(r => { const e = r.sent || r.prepared; return \`<tr><td><b>\${esc(r.label)}</b></td><td>\${pill(RT[r.status], r.status)}</td>
        <td class="small">\${e ? \`\${esc(when(e.sentAt))}\${e.sentBy ? ' · ' + esc(e.sentBy) : ''}\${r.sent?.to ? \`<br><span class="muted">to \${esc(r.sent.to)}</span>\` : r.status === 'Prepared' ? '<br><span class="muted">Word / PDF made — not emailed yet</span>' : ''}\` : '<span class="muted">—</span>'}</td>
        <td class="cc-rep-act"><button type="button" class="btn \${r.status === 'Sent' ? 'ghost' : 'primary'} small" data-open-report="\${r.key}">📄 \${r.status === 'Sent' ? 'Open' : 'Create & send'}</button></td></tr>\`; }).join('')}
      </tbody></table></div><p class="muted small">From the Sent Reports Archive. <a href="#/archive">Open the archive ›</a></p></section>\`;
    // Quick actions (from the old Home page), chosen by role: entry for supervisors, review pages for everyone.
    const qa = (h, t) => \`<a class="cc-qa" href="\${h}">\${esc(t)}</a>\`;
    const quick = [
      ...(store.can('edit') ? [qa('#/weekly', '+ Weekly labor & throughput'), qa('#/log/attendance?add=1', '+ Attendance'), qa('#/log/otif?add=1', '+ OTIF incident'), qa('#/log/damage?add=1', '+ Damage'), qa('#/safety', '+ Safety report')] : []),
      qa('#/dashboard/all', 'Dashboards'), qa('#/scorecards', 'Scorecards'), qa('#/records', 'All records'),
    ];
    return \`<div class="cc">
      <div class="cc-intro">\${esc(scope === 'all' && ids.length === 2 ? 'Both buildings' : scope === 'all' ? \`Combined Atlanta in the tiles; every location below (\${ids.join(', ')})\` : ids.map(siteLabel).join(', '))}, \${y} year to date — what is on target, what is not, and what needs action today. Click any row or item to open it.</div>
      <div class="cc-tiles">\${tiles.join('')}</div>
      <nav class="cc-quick" aria-label="Quick actions">\${quick.join('')}</nav>
      <section class="card cc-card"><div class="cc-h"><h2>Building scorecard — \${y} YTD</h2><span class="muted small">Same figures as the building dashboards</span></div>
        <div class="table-wrap"><table class="grid cc-table"><thead><tr><th>Building</th><th class="num">Order accuracy</th><th class="num">Attendance</th><th class="num">OT %</th><th class="num">Damage incidents</th><th class="num">Productivity (w/o clerical)</th><th class="num">Throughput</th><th class="num">Demurrage (est.)</th></tr></thead>
        <tbody>\${per.map(row).join('')}</tbody></table></div></section>
      \${uploadsCard()}
      \${repCard}
      <div class="cc-row">
        <section class="card cc-card"><div class="cc-h"><h2>Needs attention</h2>\${pill(ex.length ? 'bad' : 'good', ex.length ? \`\${ex.length} item\${ex.length === 1 ? '' : 's'}\` : 'All clear')}</div>
          \${ex.map(([t, n, b, d, h]) => \`<a class="exc" href="\${h}"><span class="exc-n \${t}">\${esc(String(n))}</span><span class="exc-t"><b>\${esc(b)}</b><small>\${esc(d)}</small></span><span class="exc-go">Open ›</span></a>\`).join('') || '<p class="muted">Nothing off target or overdue right now.</p>'}</section>
        <section class="card cc-card"><div class="cc-h"><h2>Rail — free time running out</h2><a class="small" href="#/rail">Rail dashboard ›</a></div>
          <div class="table-wrap"><table class="grid cc-narrow"><thead><tr><th>Car</th><th>Customer</th><th class="num">Free time</th></tr></thead><tbody>
          \${due.slice(0, 8).map(r => \`<tr data-href="#/rail/\${encodeURIComponent(r.customer || '')}" tabindex="0"><td><b>\${esc(r.car)}</b><small class="cc-sub">\${esc(r.status)} · CP \${md(r.cpDate)}</small></td><td>\${esc(r.customer || '')}<small class="cc-sub">\${fmtMoney(rate(r.customer))}/day</small></td>
            <td class="num">\${pill(r.remainingFree <= 0 ? 'bad' : 'warn', r.remainingFree <= 0 ? 'Billable' : \`\${r.remainingFree} left\`)}</td></tr>\`).join('') || '<tr><td colspan="3" class="empty">No cars near the end of free time.</td></tr>'}
          </tbody></table></div>\${due.length > 8 ? \`<p class="muted small">+ \${due.length - 8} more on the rail dashboard</p>\` : ''}</section>
        <section class="card cc-card"><div class="cc-h"><h2>Order accuracy trend</h2><span class="muted small">vs the \${fmtPct(s.orderAccuracyTarget)} target</span></div>\${chartBox('cc-acc', 230, 'Monthly order accuracy for 6049 and 6021 against the target')}</section>
      </div></div>\`;
  },
  after(root, params) {
    wireUploads(root);
    // From the bell / banner: jump to the Weekly uploads card (once).
    if (params?.query?.focus === 'uploads' && !root.dataset.focused) {
      root.dataset.focused = '1';
      requestAnimationFrame(() => root.querySelector('#weekly-uploads')?.scrollIntoView({ block: 'start', behavior: 'smooth' }));
      history.replaceState(null, '', '#/');
    }
    const s = store.settings, y = s.reportingYear, ds = mySites().map(b => ({ b, d: dashboard(b, y) })), MON = (ds[0]?.d || dashboard('all', y)).otifMonthly.map(m => ['J', 'F', 'M', 'A', 'M', 'J', 'J', 'A', 'S', 'O', 'N', 'D'][+m.start.slice(5, 7) - 1]);
    const v = d => d.otifMonthly.map(m => (m.accuracy === '' ? null : +(m.accuracy * 100).toFixed(2)));
    const lo = Math.min(95, ...ds.flatMap(x => v(x.d)).filter(x => x != null).map(x => Math.floor(x - 0.5)));
    const COL = ['#1f4a85', '#c0904d', '#7a4ea3', '#2e8b8b', '#b5523b'];
    chart('cc-acc', { type: 'line', data: { labels: MON, datasets: [
      ...ds.map(({ b, d }, i) => ({ label: b, data: v(d), borderColor: COL[i % COL.length], backgroundColor: COL[i % COL.length], pointRadius: 3, tension: .3, spanGaps: true })),
      { label: \`Target \${fmtPct(s.orderAccuracyTarget)}\`, data: MON.map(() => s.orderAccuracyTarget * 100), borderColor: '#1e8e5a', borderDash: [5, 4], pointRadius: 0, borderWidth: 1.5 }] },
      options: { plugins: { legend: { position: 'top', align: 'end' }, tooltip: { callbacks: { label: c => \`\${c.dataset.label}: \${c.parsed.y == null ? '—' : c.parsed.y.toFixed(2) + '%'}\` } } },
        scales: { x: { grid: { display: false } }, y: { min: lo, max: 100, ticks: { callback: x => x + '%' } } } } });
    // Monthly report buttons open the same report form as the dashboards / Electrolit page (data loaded first).
    root.querySelectorAll('[data-open-report]').forEach(b => b.addEventListener('click', async () => {
      const k = b.dataset.openReport, ym = reportMonth(); b.disabled = true;
      try {
        if (k === 'wr') { const [W, F] = await Promise.all([import('@atl/westrock.js'), import('@atl/forms/wrreport.js')]); await store.need(W.COLLS); F.openWrReportForm(ym); }
        else if (k === 'elx') { const [E, V] = await Promise.all([import('@atl/electrolit.js'), import('@atl/views/electrolit.js')]); await store.need(E.COLLS); V.openReportForm(ym); }
        else { const K = await import('@atl/forms/kpireport.js'); await store.need(['kpiReports', 'labor', 'throughput', 'attendance', 'otif', 'damage', 'incidents', 'monthly', 'employees']); K.openKpiReportForm(k.slice(3), ym); }
      } catch (e) { console.error(e); }
      b.disabled = false;
    }));
    // Rows open their page (mouse or Enter).
    root.querySelectorAll('tr[data-href]').forEach(tr => {
      tr.addEventListener('click', () => { location.hash = tr.dataset.href; });
      tr.addEventListener('keydown', e => { if (e.key === 'Enter') location.hash = tr.dataset.href; });
    });
  },
};`]);

