  sec.push({ id: 'sitecost', title: 'Maintenance cost by warehouse', cols: [{ h: 'Site', t: 'text' }, { h: 'Events', t: 'num' }, { h: 'Preventive', t: 'money' }, { h: 'Repairs & other', t: 'money' }, { h: 'Total', t: 'money' }, { h: 'Units', t: 'num' }, { h: 'Cost per unit', t: 'money' }],
    rows: sites.map(s => { const r = svc.filter(x => x.site === s), n = A.filter(a => a.site === s).length; return [siteLabel(s), r.length, cost(r.filter(x => /preventive/i.test(x.category))), cost(r.filter(x => !/preventive/i.test(x.category))), cost(r), n, n ? cost(r) / n : '']; }), total: true });

