  Reported: 'bad', 'Under Review': 'warn', Scheduled: 'info', 'In Progress': 'warn', Completed: 'good', Cancelled: 'neutral', Open: 'warn', Critical: 'bad', High: 'bad', Medium: 'warn', Low: 'info',
