ATL_SRC.push(['@atl/views/trainscanui.js', 0, `// Training records drop: read the scanned handouts / sign-in sheets, show each meeting found with its pages, file them.
// Rules and storage: ../trainscan.js.
import { store } from '@atl/store.js';
import { esc, toast, isISO } from '@atl/util.js';
import { readScans, saveScans, placeOf, buildingOf, dateFor, ROOT } from '@atl/trainscan.js';
import { PROGRAM, supervisors, COLLS } from '@atl/training.js';
import { mySites, canSee } from '@atl/sites.js';

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export async function openTrainingDrop(fileList, preset = {}) {
  const files = [...fileList].filter(f => /\\.pdf$/i.test(f.name) || f.type === 'application/pdf');
  if (!files.length) return toast('Drop the scanned handouts / sign-in sheets (PDF)', 'bad');
  await store.need([...COLLS, 'libDocs']);
  document.querySelector('.tr-scan-back')?.remove();
  const back = document.createElement('div'); back.className = 'modal-back tr-scan-back';
  back.innerHTML = \`<div class="modal mhe-insp" role="dialog" aria-modal="true" aria-labelledby="ts-t"><div class="modal-head"><h2 id="ts-t">Training records — signed handouts and sign-in sheets</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
    <div data-body><p class="mi-prog" data-prog>Reading \${files.length} file\${files.length === 1 ? '' : 's'}…</p></div></div>\`;
  document.body.appendChild(back);
  const close = () => back.remove();
  back.addEventListener('click', e => { if (e.target === back || e.target.closest('[data-close]')) close(); });
  let groups;
  try { groups = await readScans(files, (d, t) => { const p = back.querySelector('[data-prog]'); if (p) p.textContent = \`Reading page \${Math.min(d + 1, t)} of \${t}… (scans are read with OCR — about 3 seconds a page)\`; }); }
  catch (e) { console.error(e); back.querySelector('[data-body]').innerHTML = \`<p class="mhe-warn">Could not read the files: \${esc(e.message)}</p>\`; return; }
  for (const g of groups) { if (preset.code && !g.code) { g.code = preset.code; g.codeFrom = 'this page'; } if (preset.sup) { g.sup = preset.sup; g.building = buildingOf(preset.sup) || g.building; } if (g.code && !g.date) g.date = dateFor(g.code, g.sup); }
  const sups = supervisors(), bldgs = [...new Set([...mySites(), ...sups.map(s => String(s.building)).filter(b => b && canSee(b))])];
  const sessOpts = sel => \`<option value="">— pick the meeting —</option><optgroup label="Monthly company meetings">\${PROGRAM.monthly.map(s => \`<option value="\${s.code}"\${s.code === sel ? ' selected' : ''}>\${MON[s.month - 1]} · \${esc(s.title)}</option>\`).join('')}</optgroup><optgroup label="Monday microtrainings">\${PROGRAM.weekly.map(s => \`<option value="\${s.code}"\${s.code === sel ? ' selected' : ''}>W\${s.week} \${+s.date.slice(5, 7)}/\${+s.date.slice(8)} · \${esc(s.title)}</option>\`).join('')}</optgroup>\`;
  const tag = (txt, tone) => (txt ? \`<span class="pill \${tone}">\${esc(txt)}</span>\` : '');
  const draw = () => {
    back.querySelector('[data-body]').innerHTML = \`<p class="muted small">Each meeting is saved as one PDF named by its subject and date, in <b>SOP / Documents ▸ \${ROOT} ▸ building ▸ year ▸ month</b>, and attached to the supervisor's meeting record. Pages that name a meeting start a new record; the pages after them (the sign-in sheet) go with it. The date is the meeting's recorded delivery date, else its scheduled Monday — change it if the sheet says otherwise.</p>
      <div class="mi-list">\${groups.map(g => {
        const at = placeOf(g.code, g.sup, g.building, g.date);
        return \`<div class="mi-row" data-row="\${g.id}"><div class="ts-thumbs">\${g.pages.map((p, k) => \`<button type="button" class="mi-thumb" data-big="\${g.id}:\${k}" title="Page \${p.page} — open larger"><img src="\${p.thumb}" alt="Page \${p.page}"></button>\`).join('')}</div>
          <div class="mi-f"><div class="mi-src">\${esc(g.file.name)} · page\${g.pages.length > 1 ? 's' : ''} \${g.pages.map(p => p.page).join(', ')}</div>
            <label class="field tr-wide"><span>Meeting \${tag(g.codeFrom || 'pick', g.codeFrom ? 'good' : 'warn')}</span><select data-code>\${sessOpts(g.code)}</select></label>
            <label class="field"><span>Supervisor</span><select data-sup><option value="">—</option>\${sups.map(s => \`<option\${s.name === g.sup ? ' selected' : ''}>\${esc(s.name)}</option>\`).join('')}</select></label>
            <label class="field"><span>Building</span><select data-bldg><option value="">—</option>\${bldgs.map(b => \`<option\${b === g.building ? ' selected' : ''}>\${esc(b)}</option>\`).join('')}</select></label>
            <label class="field"><span>Meeting date</span><input type="date" data-date value="\${esc(g.date)}"></label>
            <label class="mi-skip"><input type="checkbox" data-skip\${g.skip ? ' checked' : ''}> Don’t save</label>
            <div class="mi-to small">\${g.skip ? '<span class="muted">Skipped</span>' : at ? \`Saves as <b>\${esc(at.name)}</b><br><span class="muted">\${esc(at.folder.replace(/\\//g, ' ▸ '))}\${g.sup ? \` · on \${esc(g.sup)}'s meeting record\` : ' · pick the supervisor to attach it to their meeting record'}</span>\` : '<span class="mhe-warn">Pick the meeting, building and date</span>'}</div></div></div>\`;
      }).join('')}</div>
      <div class="modal-foot"><span class="muted small" data-sum></span><div><button type="button" class="btn ghost" data-close>Cancel</button><button type="button" class="btn primary" data-save>Save records</button></div></div>\`;
    const ready = groups.filter(g => !g.skip && placeOf(g.code, g.sup, g.building, g.date)).length;
    back.querySelector('[data-sum]').textContent = \`\${ready} of \${groups.length} meeting record\${groups.length === 1 ? '' : 's'} ready\`;
  };
  draw();
  back.addEventListener('change', e => {
    const row = e.target.closest('[data-row]'), g = row && groups.find(x => x.id === row.dataset.row); if (!g) return;
    if (e.target.matches('[data-code]')) { g.code = e.target.value; g.codeFrom = g.code ? 'picked' : ''; g.date = g.code ? dateFor(g.code, g.sup) : g.date; }
    if (e.target.matches('[data-sup]')) { g.sup = e.target.value; g.building = buildingOf(g.sup) || g.building; if (g.code) g.date = dateFor(g.code, g.sup); }
    if (e.target.matches('[data-bldg]')) g.building = e.target.value;
    if (e.target.matches('[data-date]')) g.date = e.target.value;
    if (e.target.matches('[data-skip]')) g.skip = e.target.checked;
    draw();
  });
  back.addEventListener('click', async e => {
    const big = e.target.closest('[data-big]');
    if (big) { const [gid, k] = big.dataset.big.split(':'), p = groups.find(x => x.id === gid).pages[+k], w = window.open('', '_blank'); if (w) { w.document.body.style.margin = '0'; w.document.body.innerHTML = \`<img src="\${p.big}" style="width:100%">\`; } return; }
    if (!e.target.closest('[data-save]')) return;
    const todo = groups.filter(g => !g.skip), bad = todo.filter(g => !placeOf(g.code, g.sup, g.building, g.date));
    if (bad.length) return toast(\`\${bad.length} record\${bad.length === 1 ? ' needs' : 's need'} the meeting, building and date — or tick “Don’t save”\`, 'bad');
    if (!todo.length) return toast('Nothing to save', 'bad');
    const btn = e.target.closest('[data-save]'); btn.disabled = true;
    try { const n = await saveScans(todo, (d, t) => { btn.textContent = \`Saving \${Math.min(d + 1, t)} of \${t}…\`; }); toast(\`Filed \${n} training record\${n === 1 ? '' : 's'} in SOP / Documents ▸ \${ROOT}\`); close(); }
    catch (err) { console.error(err); btn.disabled = false; btn.textContent = 'Save records'; toast(err.message, 'bad'); }
  });
}`]);

